// Upload a small image already in a Blob.
async function blobToB64(blob) {
  const dataUrl = await new Promise((res, rej) => {
    const r = new FileReader();
    r.onload = () => res(r.result);
    r.onerror = rej;
    r.readAsDataURL(blob);
  });
  return dataUrl.slice(dataUrl.indexOf(",") + 1);  // strip 'data:...;base64,'
}

try {
  const out = await anna.upload.inline({
    filename:  "poster.png",
    mime_type: "image/png",
    content_b64: await blobToB64(file),
    purpose: "user_artifact",
  });
  // Save r2_key in storage; refresh download_url via upload.confirm({r2_key}) later.
  await anna.storage.set({ key: `poster:${id}`, value: { r2_key: out.r2_key } });
} catch (e) {
  if (e.code === "APP_PROVIDER_ERROR" && /TOO_LARGE/.test(e.message)) {
    // Fall back to large-file path
    await uploadViaNegotiate(file);
  } else throw e;
}

// 1) negotiate
const neg = await anna.upload.negotiate({
  filename:  "screencast.mp4",
  mime_type: "video/mp4",
  purpose:   "user_artifact",
});
await anna.storage.set({ key: `clip:${id}:r2_key`, value: neg.r2_key });   // save NOW

// 2) PUT direct to R2 — no auth header, but copy negotiate-supplied headers verbatim.
const putRes = await fetch(neg.put_url, {
  method:  "PUT",
  headers: { ...neg.headers, "content-type": "video/mp4" },
  body:    file,
});
if (!putRes.ok) throw new Error(`R2 PUT failed: ${putRes.status}`);

// 3) confirm — see upload.confirm.
const out = await anna.upload.confirm({ r2_key: neg.r2_key });

// Refresh a stale download URL using only the stored r2_key.
async function freshUrl(r2_key) {
  try {
    const out = await anna.upload.confirm({ r2_key });
    return out.download_url;
  } catch (e) {
    if (e.code === "APP_PROVIDER_ERROR" && /NOT_FOUND/.test(e.message)) {
      return null;   // user re-upload required
    }
    throw e;
  }
}
